setup.script:
d=$(dirname "$0"); printf '%s\n' "$*" >> "$d/ok.calls"
case "$1" in
 add) cat > "$d/ok.stdin"; if grep -qx "$6" "$d/ok.seen" 2>/dev/null; then st=exists; else st=queued; echo "$6" >> "$d/ok.seen"; fi; printf '{"schema":"queue-add/v1","status":"%s","id":"proj/11111111-01","lane":"lane:repo/lab-123","client_id":"%s"}\n' "$st" "$6";;
 list) printf '{"schema":"queue-stub/v1","lane":"lane:repo/lab-123","open":0,"pending":0,"commands":["list","adopt","add"]}\n';;
esac
exit 0
